export type GetFightListParams = {
  /**
   * `reporting` keeps the fights whose declaration waits for its confirmation, where disputes are; `pending` those nobody declared yet; `finished` the settled ones; `all` by default.
   */
  status?: GetFightListStatus
  /**
   * Keeps the fights of this game.
   */
  game?: string
  /**
   * A battletag or a team name, or part of one: keeps the fights of the player profiles and teams that bear it. A fight id finds that fight.
   */
  q?: string
  /**
   * Which page to read, 1 by default.
   * @minimum 1
   */
  page?: number
  /**
   * How many fights that page holds, 20 by default and 50 at most.
   * @minimum 1
   * @maximum 50
   */
  limit?: number
}

export type GetFightListStatus =
  (typeof GetFightListStatus)[keyof typeof GetFightListStatus]

